Каталог = КаталогСтруктурыТекущейБазы + "/DataProcessors/ExtCntrl";

Результат = "";
ВсеМодули = "";

// Шаг 1: Обход структуры каталога обработки
Файлы = НайтиФайлы(Каталог, "*.bsl", Истина);
Для Каждого Файл Из Файлы Цикл
	Чтение = Новый ЧтениеТекста(Файл.ПолноеИмя, КодировкаТекста.UTF8);
	Содержимое = Чтение.Прочитать();
	Чтение.Закрыть();

	ОтносительныйПуть = СтрЗаменить(Файл.ПолноеИмя, Каталог, "");
	ВсеМодули = ВсеМодули + Символы.ПС + "// ===== " + ОтносительныйПуть + " =====" + Символы.ПС + Содержимое + Символы.ПС;
КонецЦикла;

// Шаг 2: Анализ на ключевые слова песочницы
КлючевыеСлова = Новый Массив;
КлючевыеСлова.Добавить("Выполнить");
КлючевыеСлова.Добавить("Временн");
КлючевыеСлова.Добавить("Песочниц");
КлючевыеСлова.Добавить("СтрокаПодключения");
КлючевыеСлова.Добавить("CREATEINFOBASE");
КлючевыеСлова.Добавить("ЗапуститьПриложение");
КлючевыеСлова.Добавить("ВнешняяОбработка");
КлючевыеСлова.Добавить("ВнешниеОбработки");
КлючевыеСлова.Добавить("Designer");
Конфигуратор = "";
КлючевыеСлова.Добавить("ПакетныйРежим");
КлючевыеСлова.Добавить("Запрос");

НайденныеСтроки = "";

Для Каждого КлючевоеСлово Из КлючевыеСлова Цикл
	Позиция = Найти(ВРег(ВсеМодули), ВРег(КлючевоеСлово));
	Если Позиция > 0 Тогда
		НайденныеСтроки = НайденныеСтроки + КлючевоеСлово + ": ";
		// Извлекаем контекст вокруг найденного (300 символов)
		Начало = Макс(1, Позиция - 150);
		Конец = Мин(СтрДлина(ВсеМодули), Позиция + СтрДлина(КлючевоеСлово) + 150);
		Контекст = Сред(ВсеМодули, Начало, Конец - Начало);
		Контекст = СтрЗаменить(Контекст, Символы.ПС, " | ");
		НайденныеСтроки = НайденныеСтроки + Контекст + Символы.ПС;
	КонецЕсли;
КонецЦикла;

// Шаг 3: Формируем результат
Результат = "=== СТРУКТУРА МОДУЛЕЙ ОБРАБОТКИ ExtCntrl ===" + Символы.ПС;
Результат = Результат + "Найдено файлов: " + Файлы.Количество() + Символы.ПС + Символы.ПС;

Результат = Результат + "=== ПОЛНЫЙ ТЕКСТ МОДУЛЕЙ ===" + Символы.ПС;
Результат = Результат + ВсеМодули + Символы.ПС;

Результат = Результат + "=== КЛЮЧЕВЫЕ СЛОВА ПЕСОЧНИЦЫ ===" + Символы.ПС;
Если НайденныеСтроки <> "" Тогда
	Результат = Результат + НайденныеСтроки;
Иначе
	Результат = Результат + "Ключевые слова песочницы не найдены в модулях." + Символы.ПС;
КонецЕсли;
